// n8n Code Node: Run Once for All Items
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const cleanedItems = [];

for (const item of $input.all()) {
  let rawData = item.json;

  // 1. Extract raw string if output is nested under common AI keys or is direct string
  let targetStr = rawData.output || rawData.text || rawData.response || rawData;

  // 2. Parse if the target is a string (handles stringified JSON and markdown fences)
  let parsed = {};
  if (typeof targetStr === 'string') {
    try {
      // Remove markdown code blocks if the AI enclosed output in ```json ... ```
      const cleanedStr = targetStr.replace(/```json\s*|\s*```/gi, '').trim();
      parsed = JSON.parse(cleanedStr);
    } catch (err) {
      // If parsing fails, preserve error state and continue
      cleanedItems.push({
        json: {
          error: "Failed to parse JSON string",
          raw: targetStr
        }
      });
      continue;
    }
  } else if (typeof targetStr === 'object' && targetStr !== null) {
    parsed = targetStr;
  }

  // 3. Clean & Validate Fields

  // Email validation: replace sentinel values like "INVALID_EMAIL" or bad formats with null
  const rawEmail = (parsed.Email || "").trim();
  const isValidEmail = emailRegex.test(rawEmail) && !rawEmail.toUpperCase().includes("INVALID");
  const cleanedEmail = isValidEmail ? rawEmail.toLowerCase() : null;

  // Phone: keep only digits and clean leading country code/spaces if needed
  let cleanedPhone = (parsed.Phone || "").toString().replace(/\D/g, '');
  if (cleanedPhone.length === 10) {
    cleanedPhone = `+91${cleanedPhone}`; // Standardize 10-digit Indian numbers (optional)
  }

  // Enrolled Date: normalize to standard ISO format
  let formattedDate = null;
  if (parsed.Enrolled_Date) {
    const d = new Date(parsed.Enrolled_Date);
    formattedDate = isNaN(d.getTime()) ? null : d.toISOString().split('T')[0];
  }

  // 4. Assemble normalized record
  cleanedItems.push({
    json: {
      student_id: parsed.Student_ID ? parsed.Student_ID.trim() : null,
      name: parsed.Name ? parsed.Name.trim() : null,
      email: cleanedEmail,
      is_email_valid: isValidEmail,
      phone: cleanedPhone || null,
      course: parsed.Course ? parsed.Course.trim() : null,
      fee_paid: Boolean(parsed.Fee_Paid),
      city: parsed.City ? parsed.City.trim() : null,
      enrolled_date: formattedDate
    }
  });
}

return cleanedItems;
